-- FUNC11 Agro / Desenvolvimento Rural / Assistência Técnica
create schema if not exists sigov;
-- Compatibilidade idempotente para instalações que anteciparam o cadastro Agro.
alter table if exists sigov.agro_produtor add column if not exists is_deleted boolean not null default false;
create table if not exists sigov.agro_produtor (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, tipo_pessoa varchar(2) not null check(tipo_pessoa in ('PF','PJ')), nome_razao_social varchar(180) not null, cpf_cnpj varchar(14) not null, telefone varchar(30), email varchar(180), endereco text, comunidade varchar(120), localidade varchar(120), caf_pronaf varchar(80), situacao varchar(20) not null default 'ATIVO' check(situacao in ('ATIVO','INATIVO','SUSPENSO')), observacoes text, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_propriedade (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, nome varchar(180) not null, area_total numeric(14,4) not null check(area_total>=0), area_produtiva numeric(14,4) not null default 0 check(area_produtiva>=0 and area_produtiva<=area_total), localizacao text, comunidade varchar(120), latitude numeric(10,7) check(latitude between -90 and 90), longitude numeric(10,7) check(longitude between -180 and 180), car varchar(100), itr varchar(100), ccir varchar(100), situacao varchar(20) not null default 'ATIVA', observacoes text, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_cultura (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, descricao varchar(160) not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_criacao (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, descricao varchar(160) not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_atividade_produtiva (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, propriedade_id bigint not null references sigov.agro_propriedade(id), cultura_id bigint references sigov.agro_cultura(id), criacao_id bigint references sigov.agro_criacao(id), tipo varchar(20) not null check(tipo in ('CULTURA','CRIACAO','ECONOMICA')), descricao varchar(180) not null, area_quantidade numeric(14,4) check(area_quantidade>=0), unidade varchar(30), safra_periodo varchar(80), produtividade_estimada numeric(14,4) check(produtividade_estimada>=0), status varchar(20) not null default 'ATIVA', ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_visita_tecnica (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, produtor_id bigint not null references sigov.agro_produtor(id), propriedade_id bigint references sigov.agro_propriedade(id), tecnico_usuario_id bigint, tecnico_nome varchar(180), data_visita date not null, finalidade text not null, diagnostico text, recomendacoes text, retorno_previsto date, status varchar(20) not null default 'REALIZADA' check(status in ('AGENDADA','REALIZADA','CANCELADA','RETORNO')), ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_recomendacao_tecnica (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, visita_id bigint not null references sigov.agro_visita_tecnica(id), descricao text not null, prazo date, status varchar(20) not null default 'PENDENTE', ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_programa (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, nome varchar(180) not null, tipo varchar(40) not null, descricao text, inicio date, fim date, status varchar(20) not null default 'ATIVO' check(status in ('PLANEJADO','ATIVO','ENCERRADO','CANCELADO')), ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_insumo (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, codigo varchar(50) not null, descricao varchar(180) not null, unidade varchar(30) not null, saldo numeric(14,4) not null default 0 check(saldo>=0), referencia_almoxarifado_id bigint, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_patrulha_maquina (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, nome varchar(180) not null, identificacao varchar(80) not null, frota_veiculo_id bigint, horimetro numeric(14,2) not null default 0 check(horimetro>=0), situacao varchar(20) not null default 'DISPONIVEL', ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_feira (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, nome varchar(180) not null, local varchar(200) not null, data_inicio date not null, data_fim date, status varchar(20) not null default 'PLANEJADA', ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_agroindustria (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, produtor_id bigint references sigov.agro_produtor(id), nome varchar(180) not null, atividade varchar(180) not null, endereco text, comunidade varchar(120), situacao varchar(30) not null default 'ATIVA', observacoes text, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_solicitacao (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, produtor_id bigint references sigov.agro_produtor(id), propriedade_id bigint references sigov.agro_propriedade(id), tipo varchar(80) not null, descricao text not null, prioridade varchar(15) not null default 'NORMAL' check(prioridade in ('BAIXA','NORMAL','ALTA','URGENTE')), responsavel_usuario_id bigint, status varchar(20) not null default 'ABERTA' check(status in ('ABERTA','EM_ANALISE','ATRIBUIDA','CONCLUIDA','INDEFERIDA','CANCELADA')), conclusao text, concluida_em timestamptz, justificativa text, check(status not in ('INDEFERIDA','CANCELADA') or nullif(btrim(justificativa),'') is not null), ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_propriedade_produtor (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, propriedade_id bigint not null references sigov.agro_propriedade(id), produtor_id bigint not null references sigov.agro_produtor(id), principal boolean not null default false, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, unique(tenant_id,entidade_id,propriedade_id,produtor_id));
create table if not exists sigov.agro_programa_beneficiario (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, programa_id bigint not null references sigov.agro_programa(id), produtor_id bigint not null references sigov.agro_produtor(id), solicitado_em date not null default current_date, status varchar(20) not null default 'SOLICITADO' check(status in ('SOLICITADO','EM_ANALISE','APROVADO','ATENDIDO','INDEFERIDO','CANCELADO')), justificativa text, check(status not in ('INDEFERIDO','CANCELADO') or nullif(btrim(justificativa),'') is not null), ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_distribuicao_insumo (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, insumo_id bigint not null references sigov.agro_insumo(id), produtor_id bigint not null references sigov.agro_produtor(id), programa_id bigint references sigov.agro_programa(id), quantidade numeric(14,4) not null check(quantidade>0), distribuido_em date not null default current_date, observacoes text, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_servico_maquina (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, maquina_id bigint references sigov.agro_patrulha_maquina(id), produtor_id bigint not null references sigov.agro_produtor(id), propriedade_id bigint references sigov.agro_propriedade(id), tipo_servico varchar(120) not null, horas numeric(10,2) check(horas>0), data_prevista date, data_executada date, status varchar(20) not null default 'SOLICITADO' check(status in ('SOLICITADO','AGENDADO','EM_EXECUCAO','CONCLUIDO','CANCELADO')), custo_estimado numeric(14,2) check(custo_estimado>=0), ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_feirante (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, feira_id bigint not null references sigov.agro_feira(id), produtor_id bigint not null references sigov.agro_produtor(id), ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, unique(tenant_id,entidade_id,feira_id,produtor_id));
create table if not exists sigov.agro_comercializacao (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, feirante_id bigint not null references sigov.agro_feirante(id), produto varchar(180) not null, volume numeric(14,4) check(volume>=0), unidade varchar(30), valor_estimado numeric(14,2) check(valor_estimado>=0), ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_inspecao_orientacao (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, agroindustria_id bigint not null references sigov.agro_agroindustria(id), data date not null, responsavel_usuario_id bigint, responsavel_nome varchar(180), tipo varchar(20) not null check(tipo in ('ORIENTACAO','INSPECAO')), situacao text, pendencias text, prazo_regularizacao date, status varchar(20) not null default 'PENDENTE', ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
create table if not exists sigov.agro_auditoria (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, entidade varchar(80) not null, registro_id bigint, operacao varchar(40) not null, antes jsonb, depois jsonb, usuario_id bigint, correlation_id varchar(100), ip inet, created_at timestamptz not null default now());
create index if not exists ix_agro_produtor_escopo on sigov.agro_produtor(tenant_id,entidade_id);
create index if not exists ix_agro_propriedade_escopo on sigov.agro_propriedade(tenant_id,entidade_id);
create index if not exists ix_agro_cultura_escopo on sigov.agro_cultura(tenant_id,entidade_id);
create index if not exists ix_agro_criacao_escopo on sigov.agro_criacao(tenant_id,entidade_id);
create index if not exists ix_agro_atividade_produtiva_escopo on sigov.agro_atividade_produtiva(tenant_id,entidade_id);
create index if not exists ix_agro_visita_tecnica_escopo on sigov.agro_visita_tecnica(tenant_id,entidade_id);
create index if not exists ix_agro_recomendacao_tecnica_escopo on sigov.agro_recomendacao_tecnica(tenant_id,entidade_id);
create index if not exists ix_agro_programa_escopo on sigov.agro_programa(tenant_id,entidade_id);
create index if not exists ix_agro_insumo_escopo on sigov.agro_insumo(tenant_id,entidade_id);
create index if not exists ix_agro_patrulha_maquina_escopo on sigov.agro_patrulha_maquina(tenant_id,entidade_id);
create index if not exists ix_agro_feira_escopo on sigov.agro_feira(tenant_id,entidade_id);
create index if not exists ix_agro_agroindustria_escopo on sigov.agro_agroindustria(tenant_id,entidade_id);
create index if not exists ix_agro_solicitacao_escopo on sigov.agro_solicitacao(tenant_id,entidade_id);
create index if not exists ix_agro_propriedade_produtor_escopo on sigov.agro_propriedade_produtor(tenant_id,entidade_id);
create index if not exists ix_agro_programa_beneficiario_escopo on sigov.agro_programa_beneficiario(tenant_id,entidade_id);
create index if not exists ix_agro_distribuicao_insumo_escopo on sigov.agro_distribuicao_insumo(tenant_id,entidade_id);
create index if not exists ix_agro_servico_maquina_escopo on sigov.agro_servico_maquina(tenant_id,entidade_id);
create index if not exists ix_agro_feirante_escopo on sigov.agro_feirante(tenant_id,entidade_id);
create index if not exists ix_agro_comercializacao_escopo on sigov.agro_comercializacao(tenant_id,entidade_id);
create index if not exists ix_agro_inspecao_orientacao_escopo on sigov.agro_inspecao_orientacao(tenant_id,entidade_id);
create index if not exists ix_agro_auditoria_escopo on sigov.agro_auditoria(tenant_id,entidade_id);
create unique index if not exists ux_agro_produtor_documento on sigov.agro_produtor(tenant_id,entidade_id,cpf_cnpj) where not is_deleted;
create unique index if not exists ux_agro_insumo_codigo on sigov.agro_insumo(tenant_id,entidade_id,codigo) where not is_deleted;
create unique index if not exists ux_agro_maquina_identificacao on sigov.agro_patrulha_maquina(tenant_id,entidade_id,identificacao) where not is_deleted;
create unique index if not exists ux_agro_servico_agenda on sigov.agro_servico_maquina(tenant_id,entidade_id,maquina_id,data_prevista) where maquina_id is not null and data_prevista is not null and status in ('AGENDADO','EM_EXECUCAO') and not is_deleted;
-- Entrada e distribuição mantêm saldo real e impedem saldo negativo.
create or replace function sigov.agro_aplicar_distribuicao() returns trigger language plpgsql as $$ begin update sigov.agro_insumo set saldo=saldo-new.quantidade,updated_at=now() where id=new.insumo_id and tenant_id=new.tenant_id and entidade_id=new.entidade_id and saldo>=new.quantidade; if not found then raise exception 'Saldo de insumo insuficiente'; end if; return new; end $$;
drop trigger if exists trg_agro_distribuicao on sigov.agro_distribuicao_insumo; create trigger trg_agro_distribuicao before insert on sigov.agro_distribuicao_insumo for each row execute function sigov.agro_aplicar_distribuicao();
do $$ declare p text; begin foreach p in array array['AGRO_DASHBOARD_VIEW','AGRO_PRODUTOR_VIEW','AGRO_PRODUTOR_MANAGE','AGRO_PROPRIEDADE_VIEW','AGRO_PROPRIEDADE_MANAGE','AGRO_ATIVIDADE_VIEW','AGRO_ATIVIDADE_MANAGE','AGRO_ASSISTENCIA_VIEW','AGRO_ASSISTENCIA_MANAGE','AGRO_PROGRAMA_VIEW','AGRO_PROGRAMA_MANAGE','AGRO_INSUMO_VIEW','AGRO_INSUMO_MANAGE','AGRO_PATRULHA_VIEW','AGRO_PATRULHA_MANAGE','AGRO_FEIRA_VIEW','AGRO_FEIRA_MANAGE','AGRO_AGROINDUSTRIA_VIEW','AGRO_AGROINDUSTRIA_MANAGE','AGRO_SOLICITACAO_VIEW','AGRO_SOLICITACAO_MANAGE','AGRO_RELATORIO_EXPORT','AGRO_AUDITORIA_VIEW'] loop insert into sigov.permissao(modulo,chave,recurso,acao,descricao,ativo,is_deleted) select 'agro',p,'agro.'||lower(p),case when p like '%_VIEW' then 'visualizar' else 'gerenciar' end,'Permissão FUNC11 Agro e Desenvolvimento Rural',true,false where not exists(select 1 from sigov.permissao x where x.chave=p); end loop; end $$;
